import { getResponseHeader } from "h3";
export function defineNitroErrorHandler(handler) {
  return handler;
}
export function shouldDisableErrorCache(event, statusCode) {
  if (statusCode === 404) {
    return true;
  }
  const cacheControl = getResponseHeader(event, "cache-control");
  return !cacheControl || cacheControl === event.context._nitro?.routeRulesCacheControl;
}
